    }

    private void createFrozen(TestViolationStore violationStore, ArchRule rule) {
        FreezingArchRule frozen = freeze(rule).persistIn(violationStore);

        assertThatRule(frozen)
                .checking(importClasses(getClass()))
                .hasNoViolation();
    }

