        private boolean hasProblems() {
            return entries.stream().anyMatch(entry -> entry.broken || entry.resolved || entry.shared
                    || entry.misplaced || entry.colliding || entry.occupied) || !unownedFiles.isEmpty();
        }

        private String failureMessage() {
            StringBuilder message = new StringBuilder("Violation store integrity check failed:");
            appendEntries(message, "broken", entry -> entry.broken);
            appendEntries(message, "resolved", entry -> entry.resolved);
            appendEntries(message, "shared", entry -> entry.shared);
            appendEntries(message, "misplaced", entry -> entry.misplaced);
            appendEntries(message, "colliding", entry -> entry.colliding);
            appendEntries(message, "occupied", entry -> entry.occupied);
            for (Path file : unownedFiles) {
                message.append(System.lineSeparator()).append("unowned file: ").append(file.getFileName());
            }
            return message.toString();
        }

        private void appendEntries(StringBuilder message, String condition, EntryPredicate predicate) {
            entries.stream().filter(predicate::test).sorted(Comparator.comparing(entry -> entry.description))
                    .forEach(entry -> message.append(System.lineSeparator()).append(condition).append(" entry: ")
                            .append(entry.description).append(" -> ").append(entry.fileName));
