+ * default.allowStoreUpdate=...   # boolean: whether to allow updating any store file
+ * default.fileNames=random       # random, description, or a RuleViolationFileNameStrategy class
+ * default.integrity=ignore       # ignore, repair, or fail
+ * </code></pre>
+ */
+@PublicAPI(usage = ACCESS)
+public final class TextFileBasedViolationStore implements ViolationStore {
+    private static final Logger log = LoggerFactory.getLogger(TextFileBasedViolationStore.class);
+
+    private static final Pattern UNESCAPED_LINE_BREAK_PATTERN = Pattern.compile("(?<!\\\\)\\n");
+    private static final Pattern DESCRIPTION_WORD_PATTERN = Pattern.compile("(?<![A-Za-z0-9])([A-Za-z0-9]{4,120})(?![A-Za-z0-9])");
+    private static final Pattern ONLY_LINE_BREAKS_PATTERN = Pattern.compile("[\\r\\n]*");
+
+    private static final String STORE_PATH_PROPERTY_NAME = "default.path";
+    private static final String STORE_PATH_DEFAULT = "archunit_store";
+    private static final String STORED_RULES_FILE_NAME = "stored.rules";
+    private static final String ALLOW_STORE_CREATION_PROPERTY_NAME = "default.allowStoreCreation";
+    private static final String ALLOW_STORE_CREATION_DEFAULT = "false";
+    private static final String ALLOW_STORE_UPDATE_PROPERTY_NAME = "default.allowStoreUpdate";
+    private static final String ALLOW_STORE_UPDATE_DEFAULT = "true";
+    private static final String FILE_NAMES_PROPERTY_NAME = "default.fileNames";
+    private static final String FILE_NAMES_RANDOM = "random";
+    private static final String FILE_NAMES_DESCRIPTION = "description";
+    private static final String INTEGRITY_PROPERTY_NAME = "default.integrity";
+    private static final String INTEGRITY_IGNORE = "ignore";
+    private static final String INTEGRITY_REPAIR = "repair";
+    private static final String INTEGRITY_FAIL = "fail";
+
+    private static final ConcurrentHashMap<String, StoreState> STORE_STATES_BY_PATH = new ConcurrentHashMap<>();
+
+    private final RuleViolationFileNameStrategy constructorStrategy;
+
+    private boolean storeCreationAllowed;
+    private boolean storeUpdateAllowed;
+    private File storeFolder;
+    private NamingMode namingMode;
+    private RuleViolationFileNameStrategy ruleViolationFileNameStrategy;
+    private IntegrityMode integrityMode;
+    private StoreState storeState;
+
+    /**
+     * Creates a standard {@link TextFileBasedViolationStore} that names new rule violation files by random {@link UUID}s.
+     */
+    public TextFileBasedViolationStore() {
+        constructorStrategy = null;
+    }
+
+    /**
+     * Creates a {@link TextFileBasedViolationStore} with a custom strategy for rule violation file naming.
+     *
+     * @param ruleViolationFileNameStrategy controls how the rule violation file name is derived from the rule description
+     */
+    public TextFileBasedViolationStore(RuleViolationFileNameStrategy ruleViolationFileNameStrategy) {
+        this.constructorStrategy = ruleViolationFileNameStrategy;
+    }
+
+    @Override
+    public void initialize(Properties properties) {
+        storeCreationAllowed = Boolean.parseBoolean(properties.getProperty(ALLOW_STORE_CREATION_PROPERTY_NAME, ALLOW_STORE_CREATION_DEFAULT));
+        storeUpdateAllowed = Boolean.parseBoolean(properties.getProperty(ALLOW_STORE_UPDATE_PROPERTY_NAME, ALLOW_STORE_UPDATE_DEFAULT));
+        integrityMode = IntegrityMode.from(properties.getProperty(INTEGRITY_PROPERTY_NAME, INTEGRITY_IGNORE));
+        configureNaming(properties);
+
+        String path = properties.getProperty(STORE_PATH_PROPERTY_NAME, STORE_PATH_DEFAULT);
+        storeFolder = new File(path);
+        String stateKey = canonicalPath(storeFolder);
+        storeState = STORE_STATES_BY_PATH.computeIfAbsent(stateKey, ignored -> new StoreState());
+
+        synchronized (storeState) {
+            initializeLocked();
+        }
+    }
+
+    private void configureNaming(Properties properties) {
+        if (constructorStrategy != null) {
+            // getProperty() deliberately includes defaults from Properties. A caller must not be able to
+            // accidentally configure a second strategy through a Properties object with defaults.
+            if (properties.getProperty(FILE_NAMES_PROPERTY_NAME) != null) {
+                throw new StoreInitializationFailedException(String.format(
+                        "%s cannot be configured for a store constructed with a RuleViolationFileNameStrategy",
+                        FILE_NAMES_PROPERTY_NAME));
+            }
+            namingMode = NamingMode.CUSTOM;
+            ruleViolationFileNameStrategy = constructorStrategy;
+            return;
+        }
+
+        String configured = properties.getProperty(FILE_NAMES_PROPERTY_NAME, FILE_NAMES_RANDOM);
+        if (FILE_NAMES_RANDOM.equals(configured)) {
+            namingMode = NamingMode.RANDOM;
+            ruleViolationFileNameStrategy = description -> UUID.randomUUID().toString();
+        } else if (FILE_NAMES_DESCRIPTION.equals(configured)) {
+            namingMode = NamingMode.DESCRIPTION;
+            ruleViolationFileNameStrategy = TextFileBasedViolationStore::createDescriptionFileName;
+        } else {
+            namingMode = NamingMode.CUSTOM;
+            ruleViolationFileNameStrategy = instantiateStrategy(configured);
+        }
+    }
+
+    @SuppressWarnings("unchecked")
+    private RuleViolationFileNameStrategy instantiateStrategy(String className) {
+        try {
+            Class<?> strategyClass = Class.forName(className);
+            if (!RuleViolationFileNameStrategy.class.isAssignableFrom(strategyClass)) {
+                throw new IllegalArgumentException("does not implement " + RuleViolationFileNameStrategy.class.getName());
+            }
+            Constructor<?> constructor = strategyClass.getConstructor();
+            return (RuleViolationFileNameStrategy) constructor.newInstance();
+        } catch (ClassNotFoundException | NoSuchMethodException | InstantiationException | IllegalAccessException |
+                 InvocationTargetException | ClassCastException | IllegalArgumentException e) {
+            throw new StoreInitializationFailedException(String.format(
+                    "%s must be random, description, or the fully-qualified name of a RuleViolationFileNameStrategy with a public no-argument constructor, but was '%s'",
+                    FILE_NAMES_PROPERTY_NAME, className), e);
+        }
+    }
+
+    private void initializeLocked() {
+        Path folderPath = storeFolder.toPath();
+        Path storedRulesPath = folderPath.resolve(STORED_RULES_FILE_NAME);
+        boolean indexExists = Files.exists(storedRulesPath, LinkOption.NOFOLLOW_LINKS);
+
+        if (!indexExists && !storeCreationAllowed) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Creating new violation store is disabled (enable by configuration %s.%s=true)",
+                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_CREATION_PROPERTY_NAME));
+        }
+
+        try {
+            if (!Files.exists(folderPath, LinkOption.NOFOLLOW_LINKS)) {
+                Files.createDirectories(folderPath);
+            }
+            if (!Files.isDirectory(folderPath)) {
+                throw new IOException("Store path is not a directory: " + folderPath);
+            }
+            if (indexExists && !Files.isRegularFile(storedRulesPath, LinkOption.NOFOLLOW_LINKS)) {
+                throw new IOException("The index is not a regular file directly in the store folder: " + storedRulesPath);
+            }
+
+            Properties properties;
+            if (indexExists) {
+                properties = loadRulesFrom(storedRulesPath);
+            } else {
+                // In fail mode the absent index is intentionally not created until after the examination.
+                properties = new Properties();
+            }
+
+            IntegritySnapshot snapshot = integrityMode == IntegrityMode.IGNORE
+                    ? null
+                    : inspect(properties);
+
+            if (integrityMode == IntegrityMode.FAIL && snapshot.hasProblems()) {
+                throw new StoreInitializationFailedException(snapshot.failureMessage());
+            }
+
+            if (!indexExists) {
+                Files.createFile(storedRulesPath);
+            }
+
+            storeState.indexPath = storedRulesPath;
+            storeState.properties = properties;
+            if (integrityMode == IntegrityMode.REPAIR) {
+                repair(snapshot, properties);
+            }
+        } catch (StoreInitializationFailedException e) {
+            throw e;
+        } catch (IOException | InvalidPathException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+    }
+
+    private Properties loadRulesFrom(Path file) {
+        Properties result = new Properties();
+        try (InputStream inputStream = Files.newInputStream(file)) {
+            result.load(inputStream);
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+        return result;
+    }
+
+    private IntegritySnapshot inspect(Properties properties) {
+        List<Entry> entries = new ArrayList<>();
+        for (Map.Entry<Object, Object> property : properties.entrySet()) {
+            entries.add(new Entry((String) property.getKey(), (String) property.getValue()));
+        }
+        entries.sort(Comparator.comparing(entry -> entry.description));
+
+        for (Entry entry : entries) {
+            entry.path = resolveEntryPath(entry.fileName);
+            entry.broken = entry.path == null || !isDirectChild(entry.path) || !isRegularFile(entry.path);
+            if (!entry.broken) {
+                entry.resolved = readLines(entry.path).isEmpty();
+            }
+            entry.derivedFileName = deriveFileName(entry.description, entry.fileName);
+            entry.misplaced = !entry.fileName.equals(entry.derivedFileName);
+        }
+
+        markShared(entries);
+        markColliding(entries);
+        for (Entry entry : entries) {
+            entry.occupied = entry.misplaced && isOccupied(entry, entries);
+        }
+
+        List<Path> unownedFiles = findUnownedFiles(entries);
+        return new IntegritySnapshot(entries, unownedFiles);
+    }
+
+    private void markShared(List<Entry> entries) {
+        Map<String, List<Entry>> entriesByName = new HashMap<>();
+        for (Entry entry : entries) {
+            entriesByName.computeIfAbsent(entry.fileName, ignored -> new ArrayList<>()).add(entry);
+        }
+        for (List<Entry> sameName : entriesByName.values()) {
+            if (sameName.size() > 1) {
+                sameName.forEach(entry -> entry.shared = true);
+            }
+        }
+        for (int i = 0; i < entries.size(); i++) {
+            for (int j = i + 1; j < entries.size(); j++) {
+                Entry first = entries.get(i);
+                Entry second = entries.get(j);
+                if (!first.broken && !second.broken && sameFile(first.path, second.path)) {
+                    first.shared = true;
+                    second.shared = true;
+                }
+            }
+        }
+    }
+
+    private void markColliding(List<Entry> entries) {
+        Map<String, List<Entry>> entriesByDerivedName = new HashMap<>();
+        for (Entry entry : entries) {
+            entriesByDerivedName.computeIfAbsent(entry.derivedFileName, ignored -> new ArrayList<>()).add(entry);
+        }
+        for (List<Entry> sameDerivedName : entriesByDerivedName.values()) {
+            if (sameDerivedName.size() > 1) {
+                sameDerivedName.forEach(entry -> entry.colliding = true);
+            }
+        }
+    }
+
+    private boolean isOccupied(Entry entry, List<Entry> entries) {
+        if (entry.fileName.equals(entry.derivedFileName)) {
+            return false;
+        }
+        Path derivedPath = resolveEntryPath(entry.derivedFileName);
+        if (derivedPath == null || !isDirectChild(derivedPath)) {
+            return true;
+        }
+        for (Entry other : entries) {
+            if (other != entry && other.fileName.equals(entry.derivedFileName)) {
+                return true;
+            }
+        }
+        return Files.exists(derivedPath, LinkOption.NOFOLLOW_LINKS);
+    }
+
+    private List<Path> findUnownedFiles(List<Entry> entries) {
+        List<Path> result = new ArrayList<>();
+        try (DirectoryStream<Path> children = Files.newDirectoryStream(storeFolder.toPath())) {
+            for (Path child : children) {
+                if (child.getFileName().toString().equals(STORED_RULES_FILE_NAME)
+                        || !Files.isRegularFile(child, LinkOption.NOFOLLOW_LINKS)) {
+                    continue;
+                }
+                boolean owned = false;
+                for (Entry entry : entries) {
+                    if (!entry.broken && sameFile(entry.path, child)) {
+                        owned = true;
+                        break;
+                    }
+                }
+                if (!owned) {
+                    result.add(child);
+                }
+            }
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+        result.sort(Comparator.comparing(path -> path.getFileName().toString()));
+        return result;
+    }
+
+    private void repair(IntegritySnapshot snapshot, Properties properties) {
+        boolean indexChanged = false;
+        try {
+            for (Entry entry : snapshot.entries) {
+                if (entry.shared) {
+                    continue;
+                }
+                if (entry.broken) {
+                    properties.remove(entry.description);
+                    indexChanged = true;
+                } else if (entry.resolved) {
+                    deleteResolvedFile(entry.path);
+                    properties.remove(entry.description);
+                    indexChanged = true;
+                } else if (entry.misplaced && !entry.colliding && !entry.occupied) {
+                    moveToDerivedName(entry);
+                    properties.setProperty(entry.description, entry.derivedFileName);
+                    indexChanged = true;
+                }
+            }
+            if (indexChanged) {
+                syncProperties();
+            }
+        } catch (IOException | InvalidPathException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+    }
+
+    private void moveToDerivedName(Entry entry) throws IOException {
+        Path source = entry.path;
+        Path target = resolveEntryPath(entry.derivedFileName);
+        if (target == null || !isDirectChild(target) || Files.exists(target, LinkOption.NOFOLLOW_LINKS)) {
+            return;
+        }
+        // Moving a symbolic link itself would leave the violation file where it was. The integrity
+        // operation is about the file reached by the entry, so move its target instead.
+        Path sourceToMove = Files.isSymbolicLink(source) ? source.toRealPath() : source;
+        Files.move(sourceToMove, target);
+    }
+
+    private void deleteResolvedFile(Path path) throws IOException {
+        if (Files.isSymbolicLink(path)) {
+            Files.delete(path.toRealPath());
+        } else if (Files.exists(path, LinkOption.NOFOLLOW_LINKS)) {
+            Files.delete(path);
+        }
+    }
+
+    @Override
+    public boolean contains(ArchRule rule) {
+        synchronized (storeState) {
+            return findEntry(normalizeDescription(rule.getDescription())) != null;
+        }
+    }
+
+    @Override
+    public void save(ArchRule rule, List<String> violations) {
+        log.trace("Storing evaluated rule '{}' with {} violations: {}", rule.getDescription(), violations.size(), violations);
+        if (!storeUpdateAllowed) {
+            throw new StoreUpdateFailedException(String.format(
+                    "Updating frozen violations is disabled (enable by configuration %s.%s=true)",
+                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_UPDATE_PROPERTY_NAME));
+        }
+
+        synchronized (storeState) {
+            String description = normalizeDescription(rule.getDescription());
+            Entry existing = findEntry(description);
+            if (integrityMode == IntegrityMode.REPAIR && violations.isEmpty()) {
+                if (existing == null) {
+                    return;
+                }
+                forget(existing);
+                return;
+            }
+
+            String fileName;
+            boolean newEntry = existing == null;
+            if (newEntry) {
+                if (integrityMode == IntegrityMode.REPAIR && violations.isEmpty()) {
+                    return;
+                }
+                fileName = deriveFileName(rule.getDescription(), null);
+                rejectMissingName(fileName);
+                validateNewFileName(fileName);
+            } else {
+                fileName = existing.fileName;
+                validateWritableFileName(fileName);
+            }
+
+            Path file = resolveEntryPathForWrite(fileName);
+            if (newEntry) {
+                writeNewFile(violations, file);
+                storeState.properties.setProperty(description, fileName);
+                try {
+                    syncProperties();
+                } catch (RuntimeException e) {
+                    deleteQuietly(file);
+                    storeState.properties.remove(description);
+                    throw e;
+                }
+            } else {
+                writeExistingFile(violations, file);
+            }
+        }
+    }
+
+    private void forget(Entry entry) {
+        if (!isSharedNow(entry)) {
+            try {
+                if (entry.path != null && !entry.broken && isIndexFile(entry.path)) {
+                    throw new IOException("A violation file must not be the stored.rules index");
+                }
+                if (entry.path != null && !entry.broken) {
+                    deleteResolvedFile(entry.path);
+                }
+            } catch (IOException e) {
+                throw new StoreUpdateFailedException(e);
+            }
+        }
+
+        storeState.properties.remove(entry.description);
+        try {
+            syncProperties();
+        } catch (RuntimeException e) {
+            storeState.properties.setProperty(entry.description, entry.fileName);
+            throw e;
+        }
+    }
+
+    private boolean isSharedNow(Entry entry) {
+        List<Entry> entries = currentEntries();
+        for (Entry other : entries) {
+            if (other == entry) {
+                continue;
+            }
+            if (entry.fileName.equals(other.fileName)
+                    || (entry.path != null && other.path != null && !entry.broken && !other.broken && sameFile(entry.path, other.path))) {
+                return true;
+            }
+        }
+        return false;
+    }
+
+    private List<Entry> currentEntries() {
+        List<Entry> result = new ArrayList<>();
+        for (Map.Entry<Object, Object> property : storeState.properties.entrySet()) {
+            Entry entry = new Entry((String) property.getKey(), (String) property.getValue());
+            entry.path = resolveEntryPath(entry.fileName);
+            entry.broken = entry.path == null || !isDirectChild(entry.path) || !isRegularFile(entry.path);
+            result.add(entry);
+        }
+        return result;
+    }
+
+    @Override
+    public List<String> getViolations(ArchRule rule) {
+        synchronized (storeState) {
+            Entry entry = findEntry(normalizeDescription(rule.getDescription()));
+            checkArgument(entry != null, "No rule stored with description '%s'", rule.getDescription());
+            List<String> result = readLines(entry.path);
+            log.trace("Retrieved stored rule '{}' with {} violations: {}", rule.getDescription(), result.size(), result);
+            return result;
+        }
+    }
+
+    private Entry findEntry(String normalizedDescription) {
+        String fileName = storeState.properties.getProperty(normalizedDescription);
+        return fileName == null ? null : new Entry(normalizedDescription, fileName);
+    }
+
+    private void validateNewFileName(String fileName) {
+        validateWritableFileName(fileName);
+        for (Map.Entry<Object, Object> property : storeState.properties.entrySet()) {
+            String otherName = (String) property.getValue();
+            if (sameName(otherName, fileName)) {
+                throw new StoreUpdateFailedException(String.format("Violation file name '%s' is already recorded", fileName));
+            }
+        }
+        Path path = resolveEntryPathForWrite(fileName);
+        if (Files.exists(path, LinkOption.NOFOLLOW_LINKS)) {
+            throw new StoreUpdateFailedException(String.format("Violation file name '%s' is already occupied", fileName));
+        }
+    }
+
+    private boolean sameName(String first, String second) {
+        if (first.equals(second)) {
+            return true;
+        }
+        Path firstPath = resolveEntryPath(first);
+        Path secondPath = resolveEntryPath(second);
+        return firstPath != null && secondPath != null && firstPath.normalize().equals(secondPath.normalize());
+    }
+
+    private void validateWritableFileName(String fileName) {
+        Path path = resolveEntryPath(fileName);
+        if (path == null || !isDirectChild(path)) {
+            throw new StoreUpdateFailedException(String.format("Violation file name '%s' does not name a file directly in the store folder", fileName));
+        }
+        try {
+            if (isIndexFile(path)) {
+                throw new StoreUpdateFailedException("A violation file must not be the stored.rules index");
+            }
+            if (Files.exists(path, LinkOption.NOFOLLOW_LINKS)) {
+                Path realPath = path.toRealPath();
+                Path realFolder = storeFolder.toPath().toRealPath();
+                if (!realFolder.equals(realPath.getParent())) {
+                    throw new StoreUpdateFailedException(String.format(
+                            "Violation file name '%s' does not lead directly into the store folder", fileName));
+                }
+            }
+        } catch (IOException e) {
+            throw new StoreUpdateFailedException(e);
+        }
+    }
+
+    private Path resolveEntryPathForWrite(String fileName) {
+        Path path = resolveEntryPath(fileName);
+        if (path == null) {
+            throw new StoreUpdateFailedException(String.format("Violation file name '%s' is not a valid path", fileName));
+        }
+        return path.normalize();
+    }
+
+    private void writeNewFile(List<String> violations, Path file) {
+        Path temporary = null;
+        try {
+            temporary = Files.createTempFile(storeFolder.toPath(), ".archunit-", ".tmp");
+            writeBytes(violations, temporary, false);
+            Files.move(temporary, file);
+        } catch (FileAlreadyExistsException e) {
+            deleteQuietly(temporary);
+            throw new StoreUpdateFailedException(e);
+        } catch (IOException e) {
+            deleteQuietly(temporary);
+            throw new StoreUpdateFailedException(e);
+        }
+    }
+
+    private void writeExistingFile(List<String> violations, Path file) {
+        try {
+            writeBytes(violations, file, true);
+        } catch (IOException e) {
+            throw new StoreUpdateFailedException(e);
+        }
+    }
+
+    private void writeBytes(List<String> violations, Path path, boolean truncate) throws IOException {
+        byte[] bytes = violationBytes(violations);
+        if (truncate) {
+            Files.write(path, bytes, StandardOpenOption.WRITE, StandardOpenOption.TRUNCATE_EXISTING);
+        } else {
+            Files.write(path, bytes, StandardOpenOption.WRITE, StandardOpenOption.TRUNCATE_EXISTING);
+        }
+    }
+
+    private byte[] violationBytes(List<String> violations) {
+        ByteArrayOutputStream result = new ByteArrayOutputStream();
+        for (String violation : violations) {
+            byte[] escaped = escape(violation).getBytes(UTF_8);
+            result.write(escaped, 0, escaped.length);
+            result.write('\n');
+        }
+        return result.toByteArray();
+    }
+
+    private List<String> readLines(Path file) {
+        String violationsText = readStoreFile(file);
+        if (ONLY_LINE_BREAKS_PATTERN.matcher(violationsText).matches()) {
+            return Collections.emptyList();
+        }
+        return Splitter.on(UNESCAPED_LINE_BREAK_PATTERN).omitEmptyStrings().splitToStream(violationsText)
+                .map(this::unescape)
+                .collect(toList());
+    }
+
+    private String readStoreFile(Path file) {
+        try {
+            return new String(toByteArray(file.toFile()), UTF_8);
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+    }
+
+    private String escape(String violation) {
+        return violation.replace("\n", "\\\n");
+    }
+
+    private String unescape(String violation) {
+        return violation.replace("\\\n", "\n");
+    }
+
+    private String deriveFileName(String ruleDescription, String currentName) {
+        if (namingMode == NamingMode.RANDOM) {
+            // Random names cannot be derived again. Existing random entries are therefore already
+            // at the only name that can be known for them.
+            return currentName == null ? ruleViolationFileNameStrategy.createRuleFileName(ruleDescription) : currentName;
+        }
+        String result = ruleViolationFileNameStrategy.createRuleFileName(ruleDescription);
+        rejectMissingName(result);
+        return result;
+    }
+
+    private void rejectMissingName(String fileName) {
+        if (fileName == null || fileName.isEmpty()) {
+            throw new StoreUpdateFailedException("The rule violation file name strategy returned no name");
+        }
+    }
+
+    private static String createDescriptionFileName(String description) {
+        String normalized = normalizeDescription(description);
+        Matcher matcher = DESCRIPTION_WORD_PATTERN.matcher(normalized);
+        String retainedWord = null;
+        while (matcher.find()) {
+            retainedWord = matcher.group(1);
+        }
+        String hash = sha256(normalized);
+        return (retainedWord == null ? "rule" : retainedWord) + "-" + hash;
+    }
+
+    private static String sha256(String input) {
+        try {
+            byte[] digest = MessageDigest.getInstance("SHA-256").digest(input.getBytes(UTF_8));
+            StringBuilder result = new StringBuilder(digest.length * 2);
+            for (byte value : digest) {
+                result.append(String.format("%02x", value & 0xff));
+            }
+            return result.toString();
+        } catch (NoSuchAlgorithmException e) {
+            throw new IllegalStateException(e);
+        }
+    }
+
+    private static String normalizeDescription(String description) {
+        return description.replace("\r\n", "\n");
+    }
+
+    private Path resolveEntryPath(String fileName) {
+        try {
+            return storeFolder.toPath().resolve(fileName);
+        } catch (InvalidPathException | NullPointerException e) {
+            return null;
+        }
+    }
+
+    private boolean isDirectChild(Path path) {
+        Path normalizedPath = path.normalize();
+        Path normalizedFolder = storeFolder.toPath().normalize();
+        return !normalizedPath.equals(normalizedFolder) && normalizedFolder.equals(normalizedPath.getParent());
+    }
+
+    private boolean isRegularFile(Path path) {
+        try {
+            return Files.isRegularFile(path);
+        } catch (SecurityException e) {
+            return false;
+        }
+    }
+
+    private boolean sameFile(Path first, Path second) {
+        try {
+            return Files.isSameFile(first, second);
+        } catch (IOException | SecurityException e) {
+            return false;
+        }
